LAYER
  NAME "cz3001_p"
  STATUS ON
  TYPE POINT
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
  DATA "the_geom FROM (SELECT gid, the_geom, clv_cz, nom_cz FROM ivea.oficinas_cz WHERE clv_cz = 1) AS t1 USING UNIQUE gid USING SRID=900913"
  ENCODING "ISO-8859-1"
  METADATA
    "wms_title" "Tantoyuca"
    "wms_enable_request" "*"
  END
  CLASS
    NAME "Tantoyuca"
    STYLE
      COLOR 235 151 78
      SYMBOL 'circulor'
      SIZE 9
      OUTLINECOLOR 0 0 0
    END
  END
END

